def control(obs):
    h = obs.get('hitch_deg', 0.0)
    steer = 1.8 * h
    cam = obs.get('views', {}).get('camera', {}) or {}
    walls = cam.get('walls', [])
    left = [d for b,d in walls if 110 <= b <= 165]
    right = [d for b,d in walls if -165 <= b <= -110]
    if left and right:
        # Nudge away from whichever trailer-side rail is closer.
        steer += max(-5.0, min(5.0, (min(right) - min(left)) * 2.0))
    steer = max(-18.0, min(18.0, steer))
    return (steer, -0.45, -23.0)

