import math
def control(obs):
    h=obs.get('hitch_deg',0.0)
    view=(obs.get('views') or {}).get('direct') or {}
    walls=view.get('walls') or []
    pts=[]
    for b,d in walls:
        a=math.radians(b)
        x=0.75+d*math.cos(a)
        y=d*math.sin(a)
        if x < -1.5 and d < 25:
            pts.append((x,y))
    sides=[]
    for sign in (-1,1):
        q=sorted((p for p in pts if p[1]*sign>0.5), key=lambda p:abs(p[0]+8.0))
        if q:
            sides.append((sign,q[0]))
    steer=1.3*h
    if len(sides)==2:
        ys=[p[1] for _,p in sides]
        center=(ys[0]+ys[1])*0.5
        # Rear-center lateral error relative to the observed corridor midpoint.
        err=center-obs.get('rig',{}).get('trailer_rear',[0,0])[1]
        steer += max(-10.0,min(10.0,-3.0*err))
    return (max(-15.0,min(15.0,steer)),-0.20,170.0)

